entity Prob_5_39_Serial_2s_Comp_vhdl is	 port (B_out: out bit; B_in, clk, reset_b: in bit);end Prob_5_39_Serial_2s_Comp_vhdl;architecture Behavioral of Prob_5_39_Serial_2s_Comp_vhdl is	constant S_0: bit := '0';	constant S_1: bit := '1';  	signal	 state, next_state: bit;begin  process (clk, reset_b) begin    if reset_b = '0' then state <= S_0;    else state <= next_state; end if;  end process;  process (state, B_in) begin    B_out <= '0';    case (state) is		when S_0 =>	if  B_in = '0' then next_state <= S_0; B_out <= '0'; 						elsif B_in = '1' then next_state <= S_1;  B_out <= '1'; end if;      when S_1 =>	 next_state <= S_1; B_out <= not B_in;      	when others => 	next_state <= S_0;	end case;   end process;end Behavioral;